from .discovery import ROOT, METHODS, geometry_groups, observations

SITE = ROOT / 'docs'
DOI = 'https://doi.org/10.1109/GCITC60406.2023.10425975'

def nav():
    links=[('Research','#research'),('Explore','#response'),('Results','#results'),('Design','#design'),('Supplement','SUPPLEMENTARY_METHODS.pdf')]
    menu=''.join(f'<a href="{target}">{name}</a>' for name,target in links)
    return f'<nav class="nav"><div class="shell"><a class="brand" href="index.html"><span class="mark">◈</span>WEAVE</a><button class="nav-toggle" id="nav-toggle" aria-label="Open navigation" aria-expanded="false">☰</button><div class="links" id="nav-links">{menu}<a class="navlink" href="{DOI}" target="_blank" rel="noopener">Research article ↗</a></div></div></nav>'

def footer():
    return f'''<footer class="footer"><div class="shell"><div class="footer-grid"><div><div class="brand"><span class="mark">◈</span>WEAVE</div><p>Performance prediction of wearable textile antennas through ant-colony optimization and kernel regression.</p></div><div><h3>Research</h3><div class="footer-links"><a href="index.html#response">Explore the antenna spectra</a><a href="index.html#results">Regression results</a><a href="SUPPLEMENTARY_METHODS.pdf">Supplementary methods (PDF)</a><a href="SUPPLEMENTARY_METHODS.md">Supplementary methods (text)</a></div></div><div><h3>Publication</h3><div class="footer-links"><a href="{DOI}">2023 GCITC article ↗</a><a href="REFERENCES.md">References</a><a href="https://github.com/rdharini2001/Wearable_antennas">Source code ↗</a></div></div></div><div class="footer-base">WEAVE · Code and interactive research companion to Raghavan et al., IEEE GCITC (2023). Electromagnetic substrate data and analytical design relations accompany the research article.</div></div></footer>'''

def page(body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#071516"><meta name="description" content="WEAVE is the code and interactive research atlas for Ant Colony Optimization Based Support Vector Regression Algorithm for Performance Prediction of Wearable Textile Antennas. Explore antenna frequency responses, ACO-SVR, textile materials, and the supplementary methods."><meta property="og:type" content="website"><meta property="og:title" content="WEAVE | Wearable Textile Antenna Research"><meta property="og:description" content="From textile geometry to signal strength. Explore the code, antenna spectra, electromagnetic design, and supplementary methods behind the GCITC paper."><title>WEAVE | Wearable Textile Antenna Research</title><link rel="stylesheet" href="assets/weave.css"><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"></head><body>{nav()}{body}{footer()}<script src="assets/research-data.js"></script><script src="assets/weave-ui.js"></script></body></html>'''

def curve_explorer():
    return '''<div class="chart-layout"><div class="panel"><div class="chart-title">FREQUENCY RESPONSE EXPLORER</div><div class="filters"><div class="field"><label for="design-select">Antenna geometry</label><select id="design-select"></select></div><div class="field"><label for="model-select">Regression family</label><select id="model-select"></select></div><div class="field"><label for="edition-mode">Response representation</label><select id="edition-mode"><option value="baseline">Kernel regression</option><option value="v2">Spectral reconstruction</option></select></div></div><svg id="response-chart" viewBox="0 0 790 320" class="chart" role="img" aria-label="Observed frequency response with held-out model predictions"></svg><div class="chart-legend"><span><i class="swatch"></i> Recorded response</span><span><i class="swatch mint"></i> Held-out prediction</span></div><div class="chart-note" id="curve-caption"></div></div><div class="panel"><span class="eyebrow">Characterized antenna</span><h3 style="margin-top:16px">The signal has a shape.</h3><p>Geometry determines how the antenna responds across frequency. The support vector regressor learns the geometry-frequency response; frequency-sweep interpolation resolves local spectral detail.</p><div class="hero-metric" id="model-mae">—</div><p>MAE · dB, held-out frequencies</p><div class="stat-pair"><div><small>RMSE · dB</small><strong id="model-rmse">—</strong></div><div><small>R²</small><strong id="model-r2">—</strong></div><div><small>MSE · dB²</small><strong id="model-mse">—</strong></div><div><small>Design</small><strong>Textile patch</strong></div></div><div class="data-row"><span>Current design</span><strong id="design-measures">—</strong></div><p class="note">Held-out frequency prediction for a characterized antenna geometry.</p></div></div>'''

def fabric_cards():
    materials=[('Cotton / air','6.8','1.1'),('Cotton / body','9.6','1.1'),('Polyester','4.7','4.2'),('Poly-amide','5.9','2.7')]
    logo='<svg viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M2 7h24M2 14h24M2 21h24M7 2v24M14 2v24M21 2v24" stroke="#77d6b8" stroke-width="1.2"/><path d="M7 7h7v7H7zM14 14h7v7h-7z" fill="#c9956d" opacity=".65"/></svg>'
    return '<div class="material-grid">'+''.join(f'<div class="material">{logo}<small>{n}</small><strong>{v} <span>dBi</span></strong><span>Relative permittivity εᵣ = {eps}</span></div>' for n,v,eps in materials)+'</div>'

def calculator():
    return '''<div class="geometry-panel"><div class="panel"><span class="eyebrow">Analytical microstrip design</span><h3 style="margin-top:16px">Antenna dimensions, from first principles</h3><p>Rectangular microstrip design accounts for effective permittivity and fringing-length corrections. Explore the influence of substrate and resonance.</p><div class="filters"><div class="field"><label for="resonance">Frequency · <span id="resonance-value">2.4</span> GHz</label><input id="resonance" aria-label="Resonant frequency" type="range" min="1.5" max="3.5" step="0.1" value="2.4" style="width:100%;accent-color:#e7b487"></div><div class="field"><label for="permittivity">εᵣ · <span id="permittivity-value">1.1</span></label><input id="permittivity" aria-label="Relative permittivity" type="range" min="1.1" max="4.2" step="0.1" value="1.1" style="width:100%;accent-color:#e7b487"></div><div class="field"><label for="substrate-height">Height · <span id="height-value">1.5</span> mm</label><input id="substrate-height" aria-label="Substrate thickness" type="range" min="0.5" max="3" step="0.1" value="1.5" style="width:100%;accent-color:#e7b487"></div></div><div class="stat-pair"><div><small>Patch width</small><strong id="patch-width">—</strong></div><div><small>Patch length</small><strong id="patch-length">—</strong></div><div><small>Ground width</small><strong id="ground-width">—</strong></div><div><small>Ground length</small><strong id="ground-length">—</strong></div></div><p class="note">Analytical geometry only. Use the analytical dimensions as a starting point for electromagnetic design and material selection.</p></div><div><svg viewBox="0 0 570 390" role="img" aria-label="Exploded textile antenna layers"><defs><linearGradient id="topcu" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#f3cca0"/><stop offset="1" stop-color="#9c5e40"/></linearGradient></defs><path d="M55 254 280 143 523 252 295 363Z" fill="#132d2c" stroke="#478a7b" stroke-width="2"/><path d="M55 227 280 116 523 225 295 336Z" fill="#296458" stroke="#7bd2af" stroke-width="2"/><path d="M84 165 287 66 500 167 296 267Z" fill="url(#topcu)" stroke="#ffe0ae" stroke-width="2"/><path d="M84 165 287 66 500 167 296 267Z" fill="none" stroke="#f4deb0" stroke-width=".5" stroke-dasharray="3 7"/><path d="M155 165 219 133 260 149 195 183Z" fill="#143c38" stroke="#ffd7a1"/><path d="M364 137 412 160 380 175 333 153Z" fill="#143c38" stroke="#ffd7a1"/><path d="M54 254v20l241 109v-20M295 363v20l228-112v-19" fill="#113f3c" stroke="#518f79"/><path d="M52 201h79M418 91h95M457 323h72" stroke="#b4d9c5" stroke-dasharray="3 7"/><g fill="#c6e1d3" font-size="12" font-family="Arial,sans-serif" letter-spacing="1"><text x="49" y="190">RADIATOR</text><text x="420" y="80">SUBSTRATE</text><text x="451" y="342">GROUND</text></g></svg></div></div>'''

def homepage(baseline, enhanced, blind, transport):
    def f(v,precision=3): return f'{v:.{precision}f}'
    body=f'''<header class="hero"><div class="shell hero-grid"><div class="hero-copy"><span class="overline">THE RESEARCH COMPANION · IEEE GCITC 2023</span><h1>Fabric meets<br><i>frequency.</i></h1><p>Explore how patch geometry, fabric substrates and operating frequency shape the response of a wearable antenna. A visual research atlas for ant-colony optimized support vector regression of textile antennas.</p><div class="buttons"><a class="btn" href="#response">Explore antenna spectra ↘</a><a class="btn quiet" href="SUPPLEMENTARY_METHODS.pdf">Supplementary methods ↗</a></div></div><div class="hero-visual"><img src="assets/antenna-atlas.svg" class="hero-image" width="900" height="840" alt="Isometric wearable copper patch antenna surrounded by radio-frequency field contours"><div class="telemetry">Textile patch antenna<strong>2.4 GHz</strong>Wearable RF systems</div></div></div></header>
    <div class="index-rule"><div class="shell ribbon"><div><strong>1,266</strong><span>Observed responses</span></div><div><strong>08</strong><span>Patch geometries</span></div><div><strong>12</strong><span>Regressor families</span></div><div><strong>ACO–SVR</strong><span>Core prediction model</span></div></div></div>
    <section class="section" id="research"><div class="shell"><div class="section-title"><div><span class="eyebrow">THE INVESTIGATION</span><h2>From patch geometry<br>to signal strength.</h2></div><p>The research relates patch geometry and operating frequency to textile antenna performance through ant-colony optimized support vector regression. Explore the antenna spectra, material behavior, model predictions and design equations.</p></div><div class="triple"><div class="key-tile"><div class="big">01</div><h3>Shape</h3><p>Patch and slot dimensions define eight antenna geometries. Their recorded frequency sweeps reveal the features behind their distinct resonant responses.</p></div><div class="key-tile"><div class="big">02</div><h3>Predict</h3><p>A colony-inspired search selects the Gaussian support vector regressor, connecting antenna geometry and operating frequency to measured signal strength.</p></div><div class="key-tile"><div class="big">03</div><h3>Characterize</h3><p>Spectral refinement follows resonant detail between observations, while frequency-marginal modeling describes the range of responses when frequency is unspecified.</p></div></div><div class="article-citation"><div><span class="eyebrow">RESEARCH ARTICLE · IEEE GCITC 2023</span><h3>Ant Colony Optimization Based Support Vector Regression Algorithm for Performance Prediction of Wearable Textile Antennas</h3><p>D. Raghavan · B. Sujatha · Chinmayi B. S. · Bhavana B. Rao · John Kiran</p><span class="article-doi">DOI: 10.1109/GCITC60406.2023.10425975</span></div><a href="{DOI}" class="citation-arrow" aria-label="Open the IEEE research article">↗</a></div><div class="buttons" style="margin-top:28px"><a class="btn quiet" href="SUPPLEMENTARY_METHODS.pdf">Supplementary methods ↗</a><a class="btn quiet" href="{DOI}">Read the article ↗</a></div></div></section>
    <section class="section alt" id="response"><div class="shell"><div class="section-title"><div><span class="eyebrow">INTERACTIVE FREQUENCY RESPONSE</span><h2>See the spectrum unfold.</h2></div><p>Choose an antenna configuration and model. Copper traces show the observed response; mint markers show independently held-out predictions.</p></div>{curve_explorer()}</div></section>
    <section class="section" id="results"><div class="shell"><div class="section-title"><div><span class="eyebrow">REGRESSION PERFORMANCE</span><h2>Precision across<br>the spectrum.</h2></div><p>Signal-strength prediction across characterized wearable antenna geometries, evaluated at held-out operating frequencies.</p></div><div class="metric-cards"><div class="metric-card"><small>MSE · dB²</small><strong>{f(baseline.mse)}</strong><em>Mean squared error</em></div><div class="metric-card"><small>RMSE · dB</small><strong>{f(baseline.rmse)}</strong><em>Root mean squared error</em></div><div class="metric-card"><small>MAE · dB</small><strong>{f(baseline.mae)}</strong><em>Mean absolute error</em></div><div class="metric-card"><small>R²</small><strong>{f(baseline.r2)}</strong><em>Explained variance</em></div></div><p class="bottom-note">ACO–SVR response predictions for a geometry-stratified 25% frequency holdout. The mathematical formulation and experimental partition are described in the supplementary information.</p><div class="panel" style="margin-top:34px"><div class="filters" style="margin-top:0"><div class="field"><label for="baseline-mode">Input configuration</label><select id="baseline-mode"><option value="with">With operating frequency</option><option value="without">Geometry only</option></select></div><div style="flex:2"><p class="note">Explore twelve regression families across frequency-aware and geometry-only prediction. Each row reports the held-out metrics calculated for that estimator.</p></div></div><div class="table-window"><table class="results-table"><thead><tr><th>Regressor</th><th>MSE</th><th>RMSE</th><th>MAE</th><th>R²</th></tr></thead><tbody id="baseline-table"></tbody></table></div><div class="buttons" style="margin-top:20px"><a class="btn quiet" href="downloads/regression_metrics.csv">Download regression results ↓</a><a class="btn quiet" href="SUPPLEMENTARY_METHODS.pdf">Mathematical methods ↗</a></div></div></div></section>
    <section class="section alt" id="spectral"><div class="shell"><div class="section-title"><div><span class="eyebrow">SPECTRAL REFINEMENT</span><h2>The fine structure<br>of resonance.</h2></div><p>A resonant antenna rarely responds in straight lines. Local spectral correction resolves the fine structure of frequency sweeps for antenna geometries already represented during training.</p></div><div class="formula">ŷ(g, f) = f<sub>ACO–SVR</sub>(g, f) + s<sub>g</sub>(f)</div><div class="triple" style="margin-top:35px"><div class="key-tile"><div class="big">{f(enhanced.mae)}</div><h3>Refined MAE · dB</h3><p>Compared with {f(baseline.mae)} for ACO–SVR alone on the same held-out frequencies.</p></div><div class="key-tile"><div class="big">{f(enhanced.rmse)}</div><h3>Refined RMSE · dB</h3><p>Frequency-response interpolation within characterized antenna designs.</p></div><div class="key-tile"><div class="big">{f(enhanced.r2)}</div><h3>Refined R²</h3><p>Spectral interpolation selected by validation on the training frequency sweeps.</p></div></div><p class="bottom-note">The global regression model and local spectral reconstruction work together to characterize smooth responses and narrow resonant features.</p></div></section>
    <section class="section" id="design"><div class="shell"><div class="section-title"><div><span class="eyebrow">ANTENNA DESIGN</span><h2>From equations<br>to textiles.</h2></div><p>Rectangular microstrip relations connect operating frequency, dielectric constant, patch dimensions and the ground plane.</p></div>{calculator()}</div></section>
    <section class="section alt" id="materials"><div class="shell"><div class="section-title"><div><span class="eyebrow">ELECTROMAGNETIC CHARACTERIZATION</span><h2>Designed to be worn.</h2></div><p>HFSS gain patterns across textile substrate materials and the presence of body tissue at 2.4 GHz.</p></div>{fabric_cards()}<p class="bottom-note">HFSS material characterization at 2.4 GHz. The accompanying research article provides the full antenna simulation study and reflection-coefficient analysis.</p></div></section>
    <section class="section" id="distribution"><div class="shell"><div class="section-title"><div><span class="eyebrow">WHEN FREQUENCY IS NOT KNOWN</span><h2>Predict the response<br>distribution.</h2></div><p>A geometry alone cannot determine which point on its frequency sweep is being sampled. The frequency-marginal estimator instead predicts a distribution over the observed band.</p></div><div class="chart-layout"><div class="panel"><div class="filters"><div class="field"><label for="quantile-select">Antenna geometry</label><select id="quantile-select"></select></div></div><svg class="chart" viewBox="0 0 790 320" id="quantile-chart" role="img" aria-label="Observed and predicted response quantiles"></svg><div class="chart-legend"><span><i class="swatch"></i> Held-out response quantiles</span><span><i class="swatch mint"></i> Predicted response quantiles</span></div></div><div class="panel"><span class="eyebrow">FREQUENCY-MARGINAL MODEL</span><h3 style="margin-top:18px">Characterizing uncertainty.</h3><div class="stat-pair"><div><small>Wasserstein-1 · dB</small><strong id="transport-w1">—</strong></div><div><small>Wasserstein-2 · dB</small><strong id="transport-w2">—</strong></div><div><small>Squared W₂ · dB²</small><strong id="transport-w2sq">—</strong></div><div><small>Distribution R²</small><strong id="transport-r2">—</strong></div></div><p class="note">Distributional scores compare response quantiles and are not interchangeable with pointwise MAE, RMSE or R².</p></div></div></div></section>
    <section class="section alt" id="supplement"><div class="shell split-text"><div><span class="eyebrow">SUPPLEMENTARY RESEARCH METHODS</span><h2 style="margin-top:18px">The mathematics<br>behind the model.</h2><p style="margin-top:22px">Detailed derivations connect the kernel regression objective, ant-colony parameter search, frequency-domain reconstruction, uncertainty quantification and analytical textile patch design.</p></div><div class="panel"><span class="eyebrow">IEEE GCITC · 2023 · DOI 10.1109/GCITC60406.2023.10425975</span><h3 style="margin-top:18px">One paper. A complete research atlas.</h3><p>The research article, executable regression models, frequency-response data and detailed supplementary methods form a single, accessible scientific resource.</p><div class="buttons"><a class="btn" href="SUPPLEMENTARY_METHODS.pdf">Supplementary methods · PDF ↗</a><a class="btn quiet" href="SUPPLEMENTARY_METHODS.md">Read online ↗</a><a class="btn quiet" href="REFERENCES.md">References ↗</a></div></div></div></section>'''
    return page(body)


def build():
    df=observations();g=geometry_groups(df)
    scores=pd.read_csv(ROOT/'results/enhanced/metrics.csv')
    p=pd.read_csv(ROOT/'results/enhanced/predictions.csv',usecols=['protocol','frequency_mode','algorithm','variant','group','testfreq','predicted_db'])
    p=p[(p.protocol=='frequency_interpolation')&(p.frequency_mode=='with')&(p.variant.isin(['kernel_regression','spectral_residual_hybrid']))]
    geom=['PatchLength','PatchWidth','SlotLength','SlotWidth']
    designs={int(gid):[float(z) for z in df.loc[g==gid,geom].iloc[0].to_list()] for gid in sorted(set(g))}
    dataset={'designs':[{'id':i,'geometry':vec} for i,vec in designs.items()],
         'points':[[round(float(row.TestFreq),9),round(float(row.Strength),6),int(g[k])] for k,row in df.iterrows()],
         'algorithms':list(METHODS),
         'metrics':scores[scores.protocol.eq('frequency_interpolation')].to_dict('records'),
         'predictions':p.drop(columns='protocol').round(7).to_dict('records'),
         'transport':json.loads((ROOT/'results/transport/metrics.json').read_text()),
         'quantiles':pd.read_csv(ROOT/'results/transport/rank_couplings.csv').round(6).to_dict('records')}
    def chosen(mode,variant):
        result=scores[(scores.protocol=='frequency_interpolation')&(scores.frequency_mode==mode)&(scores.algorithm=='ACO-SVM')&(scores.variant==variant)]
        if len(result)!=1:raise ValueError('Missing ACO-SVR scores')
        return result.iloc[0]
    SITE.mkdir(parents=True,exist_ok=True)
    (SITE/'assets').mkdir(exist_ok=True)
    downloads=SITE/'downloads';downloads.mkdir(exist_ok=True)
    for filename,source in [('regression_metrics.csv','results/enhanced/metrics.csv'),('seed_stability.csv','results/transport/seed_stability.csv'),('frequency_blind_intervals.csv','results/marginal/forecasts.csv')]:
        shutil.copyfile(ROOT/source,downloads/filename)
    (SITE/'assets'/'research-data.js').write_text('window.WEAVE_DATA='+json.dumps(dataset,separators=(',',':'),allow_nan=False).replace('</','<\\/')+';\n')
    (SITE/'index.html').write_text(homepage(chosen('with','kernel_regression'),chosen('with','spectral_residual_hybrid'),chosen('without','geometry_pooled_blind'),dataset['transport']))
    for old in ('study-one.html','study-two.html','methods.html'):
        (SITE/old).unlink(missing_ok=True)
    print('WEAVE research website generated')

if __name__=='__main__':build()
